<?php require __DIR__.'/layout.php';$rows=db()->query("SELECT * FROM media WHERE published=1 ORDER BY featured DESC,sort_order,id DESC")->fetchAll();site_header('Galeria');?>
<main id="conteudo-principal" class="content-page"><header class="page-banner"><span>MEMÓRIA VISUAL</span><h1>Galeria de Fotos e Vídeos</h1><p>Momentos marcantes da Banda Amaral Brasil.</p></header><div class="media-grid"><?php foreach($rows as $m):?><article class="media-card"><?php if($m['media_type']==='IMAGE'&&$m['file_path']):?><img src="<?=e($m['file_path'])?>" alt="<?=e($m['title'])?>"><?php elseif($m['media_type']==='VIDEO'&&$m['file_path']):?><video controls preload="metadata" aria-label="<?=e($m['title']?:'Vídeo da BAMAB')?>"><source src="<?=e($m['file_path'])?>"></video><?php elseif($m['media_type']==='INSTAGRAM'):?><?=render_instagram_embed($m['instagram_url'])?><?php endif;?><div><h3><?=e($m['title'])?></h3><p><?=e($m['caption'])?></p></div></article><?php endforeach;?></div><?php if(!$rows):?><div class="empty-public">A galeria está pronta para receber todas as fotos e vídeos oficiais.</div><?php endif;?></main><?php site_footer();?>